#!/usr/bin/env node

// Explicit, consent-gated SDK setup. Ported from the old postinstall MINUS all
// network code: docs are copied from the bundled `docs/` dir (see copy-docs.mjs)
// rather than downloaded. Nothing here runs on bare `npm install`; it only runs
// when a user invokes `npx rundot-sdk-setup`.

import {
  existsSync,
  rmSync,
  readFileSync,
  writeFileSync,
  readdirSync,
  cpSync,
  mkdirSync,
  realpathSync,
} from 'fs';
import { resolve as resolvePath, dirname, join, basename } from 'path';
import { fileURLToPath } from 'url';
import { createInterface } from 'readline';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const VERSION_FILE = '.sdk-version';

// The four write categories, in prompt order. Every filesystem write in this
// script is attached to exactly one of these and only happens when
// consent.write(category) is true.
const CATEGORY_KEYS = ['docs', 'agents', 'gitignore', 'hooks'];

// Prompt labels derive from the resolved on-disk paths so a legacy `.rundot/`
// install shows `.rundot/docs`, not the canonical `rundot/docs`.
export function categoryLabels(docsRel, rundotRel) {
  return {
    docs: `Copy SDK docs into ${docsRel}`,
    agents: 'Create/update AGENTS.md, CLAUDE.md, GEMINI.md',
    gitignore: `Add ${docsRel} to .gitignore`,
    hooks: `Configure ${rundotRel}/cli_hooks.json CLI hooks`,
  };
}

/**
 * Resolve the single project-local rundot folder, mirroring the CLI's
 * RundotPaths.ResolveExisting: prefer the canonical visible `rundot/`, fall back
 * to the legacy hidden `.rundot/`, create `rundot/` only when neither exists.
 */
function resolveRundotDir(projectRoot) {
  const canonical = resolvePath(projectRoot, 'rundot');
  const legacy = resolvePath(projectRoot, '.rundot');
  if (existsSync(canonical)) return canonical;
  if (existsSync(legacy)) return legacy;
  return canonical;
}

function getCurrentVersion() {
  try {
    const packageJsonPath = resolvePath(__dirname, '..', 'package.json');
    const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf-8'));
    return packageJson.version;
  } catch {
    return null;
  }
}

function findAgentFiles(dir, results = []) {
  if (!existsSync(dir)) return results;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const fullPath = join(dir, entry.name);
    if (entry.name === '.git' || entry.name === 'node_modules') continue;
    if (entry.isDirectory()) {
      findAgentFiles(fullPath, results);
    } else if (entry.isFile()) {
      const nameLower = entry.name.toLowerCase();
      if (nameLower === 'agents.md' || nameLower === 'claude.md') {
        results.push(fullPath);
      }
    }
  }
  return results;
}

function injectAgentsIndex(filePath, agentsIndexContent) {
  const content = readFileSync(filePath, 'utf-8');
  const openTag = '<agents-index>';
  const closeTag = '</agents-index>';
  const openIndex = content.indexOf(openTag);
  const closeIndex = content.indexOf(closeTag);

  let newContent;
  if (openIndex !== -1 && closeIndex !== -1 && closeIndex > openIndex) {
    const before = content.substring(0, openIndex + openTag.length);
    const after = content.substring(closeIndex);
    newContent = `${before}\n${agentsIndexContent}${after}`;
  } else {
    newContent = `${openTag}\n${agentsIndexContent}${closeTag}\n\n${content}`;
  }
  writeFileSync(filePath, newContent, 'utf-8');
}

/**
 * Rewrite the agents-index `root:` token to the actual resolved docs path so a
 * legacy `.rundot/` consumer gets an index pointing at `./.rundot/docs`, not the
 * hardcoded `root:./rundot/docs` shipped in agents-index.txt.
 */
function withIndexRoot(content, docsRel) {
  return content.replace(/root:\.\/[^|]*/, `root:./${docsRel}`);
}

// ---------------------------------------------------------------------------
// Consent
// ---------------------------------------------------------------------------

/**
 * Resolve the single consent value once. Returns either
 *   { mode: 'error', message }                  → caller exits non-zero
 *   { mode: 'skip-noninteractive' }             → caller prints opt-in hint, exit 0
 *   { write: (category) => boolean, prompt? }   → routed writes
 *
 * Pure (no I/O) so it can be unit-tested. `prompt` is provided by the caller
 * for the interactive path; here we only decide which path applies.
 */
export function resolveConsent({ args, isTTY }) {
  const yes = args.includes('-y') || args.includes('--yes');
  const no = args.includes('--no');

  if (yes && no) {
    return {
      mode: 'error',
      message: 'Conflicting flags: --yes and --no cannot be used together.',
    };
  }
  if (yes) return { mode: 'all' };
  if (no) return { mode: 'none' };
  if (isTTY) return { mode: 'interactive' };
  return { mode: 'skip-noninteractive' };
}

function askYesNo(rl, question) {
  return new Promise((resolve) => {
    rl.question(`${question} [y/N] `, (answer) => {
      resolve(/^y(es)?$/i.test(answer.trim()));
    });
  });
}

/**
 * Build the single `confirmWrite(category)` gate from the resolved consent mode.
 * For interactive mode, prompts once per category up front (default No) and
 * caches the answers so the rest of the run can ask the gate freely.
 */
async function buildGate(consent, labels) {
  if (consent.mode === 'all') {
    return { write: () => true };
  }
  if (consent.mode === 'none') {
    return { write: () => false };
  }
  // interactive
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  const answers = {};
  try {
    for (const category of CATEGORY_KEYS) {
      answers[category] = await askYesNo(rl, labels[category] + '?');
    }
  } finally {
    rl.close();
  }
  return { write: (category) => answers[category] === true };
}

// ---------------------------------------------------------------------------
// Write actions — each takes the gate and writes only when its category passes
// ---------------------------------------------------------------------------

function copyDocs(gate, bundledDocs, docsDir, version) {
  if (!gate.write('docs')) return false;
  rmSync(docsDir, { recursive: true, force: true });
  mkdirSync(dirname(docsDir), { recursive: true });
  cpSync(bundledDocs, docsDir, { recursive: true });

  if (version) {
    writeFileSync(join(docsDir, VERSION_FILE), version, 'utf-8');
  }
  console.log(`   Copied docs into ${docsDir}`);
  return true;
}

/**
 * The single injection decision: inject the agents-index iff the agents
 * category was consented AND the docs it references will be on disk at the
 * resolved docsDir (freshly copied this run, or already present from a prior
 * run). Pure so it can be unit-tested; `main` resolves the inputs once.
 */
export function shouldInjectAgents({ agentsConsented, docsOnDisk }) {
  return agentsConsented && docsOnDisk;
}

/**
 * Resolve the agents-index content from whichever docs source is available:
 * the just-copied/on-disk `docsDir` if present, else the bundled docs that
 * ship in the package. Returns null only when the index exists in neither —
 * the one case where injecting would point at docs that don't exist.
 */
export function resolveAgentsIndex(docsDir, bundledDocs, docsRel) {
  const candidate = [join(docsDir, 'agents-index.txt'), join(bundledDocs, 'agents-index.txt')]
    .find((path) => existsSync(path));
  if (!candidate) return null;
  return withIndexRoot(readFileSync(candidate, 'utf-8').trim(), docsRel);
}

function processAgentFiles(gate, agentsIndexContent, projectRoot) {
  if (!gate.write('agents')) return;

  if (agentsIndexContent == null) {
    console.log('   No agents-index.txt found, skipping agent files injection');
    return;
  }

  const agentFiles = findAgentFiles(projectRoot);
  if (agentFiles.length === 0) {
    for (const file of ['AGENTS.md', 'CLAUDE.md', 'GEMINI.md']) {
      const p = join(projectRoot, file);
      writeFileSync(p, '', 'utf-8');
      console.log(`   Created ${file}`);
      agentFiles.push(p);
    }
  }

  for (const filePath of agentFiles) {
    try {
      injectAgentsIndex(filePath, agentsIndexContent);
      console.log(`   Injected agents-index into ${filePath.replace(projectRoot + '/', '')}`);
    } catch (error) {
      console.warn(`   Failed to inject into ${filePath}:`, error.message);
    }
  }
}

function updateGitignore(gate, projectRoot, docsRel) {
  if (!gate.write('gitignore')) return;

  const gitignorePath = join(projectRoot, '.gitignore');
  if (!existsSync(gitignorePath)) return;

  const content = readFileSync(gitignorePath, 'utf-8');
  if (content.includes(docsRel)) return;

  const entry = `${docsRel}/`;
  const newContent = content.endsWith('\n')
    ? `${content}${entry}\n`
    : `${content}\n${entry}\n`;
  writeFileSync(gitignorePath, newContent, 'utf-8');
  console.log(`   Added ${entry} to .gitignore`);
}

function setupCliHooks(gate, rundotDir, version) {
  if (!gate.write('hooks')) return;

  const hooksFilePath = resolvePath(rundotDir, 'cli_hooks.json');
  const newHookEntry = {
    name: 'check-sdk-version',
    command: `echo RUN.world SDK v${version || 'unknown'}`,
    blocking: false,
  };

  mkdirSync(rundotDir, { recursive: true });

  const hooksData = existsSync(hooksFilePath)
    ? JSON.parse(readFileSync(hooksFilePath, 'utf-8'))
    : {};
  hooksData.hooks ??= {};
  if (!Array.isArray(hooksData.hooks['pre-command'])) {
    hooksData.hooks['pre-command'] = [];
  }
  const preCommand = hooksData.hooks['pre-command'];
  const idx = preCommand.findIndex((h) => h.name === 'check-sdk-version');
  if (idx !== -1) preCommand[idx] = newHookEntry;
  else preCommand.push(newHookEntry);

  writeFileSync(hooksFilePath, JSON.stringify(hooksData, null, 2) + '\n', 'utf-8');
  console.log(`   CLI hooks configured at ${basename(rundotDir)}/cli_hooks.json`);
}

function findProjectRoot() {
  const currentDir = process.cwd();
  if (currentDir.includes('node_modules')) {
    return currentDir.split('node_modules')[0];
  }
  return currentDir;
}

async function main() {
  const consent = resolveConsent({
    args: process.argv.slice(2),
    isTTY: Boolean(process.stdin.isTTY),
  });

  if (consent.mode === 'error') {
    console.error(consent.message);
    process.exit(2);
  }

  const projectRoot = findProjectRoot();
  const rundotDir = resolveRundotDir(projectRoot);
  const docsDir = join(rundotDir, 'docs');
  const rundotRel = basename(rundotDir);
  const docsRel = `${rundotRel}/docs`;
  const bundledDocs = resolvePath(__dirname, '..', 'docs');
  const labels = categoryLabels(docsRel, rundotRel);

  if (consent.mode === 'skip-noninteractive') {
    console.log('RUN.world SDK setup: no TTY and no -y flag, writing nothing.');
    console.log('Would have (with -y):');
    console.log(`   - ${labels.docs} (from bundled docs)`);
    console.log(`   - ${labels.agents}`);
    console.log(`   - ${labels.gitignore}`);
    console.log(`   - ${labels.hooks}`);
    console.log('Re-run with -y to apply, or run in an interactive terminal.');
    process.exit(0);
  }

  const gate = await buildGate(consent, labels);
  const version = getCurrentVersion();
  const bundledDocsAvailable = existsSync(bundledDocs);

  // Copy docs only when consented; require the bundle only on that path so the
  // no-op / hooks-only / --no runs never depend on the bundle being present.
  let docsWritten = false;
  let docsRequestedButUnavailable = false;
  if (gate.write('docs')) {
    if (bundledDocsAvailable) {
      docsWritten = copyDocs(gate, bundledDocs, docsDir, version);
    } else {
      docsRequestedButUnavailable = true;
      console.error(
        `RUN.world SDK setup: cannot copy docs — bundled docs missing at ${bundledDocs}. ` +
          'This indicates a packaging error in the published SDK.',
      );
    }
  }

  // The agents-index may only be injected when the docs it references will
  // actually be on disk at the resolved docsDir: either freshly copied this run
  // or already present from a prior run. The bundled docs are still the source
  // of the index text, but they are never themselves the trigger — injecting
  // off the bundle alone would point AGENTS/CLAUDE/GEMINI at docs that don't
  // exist on disk.
  const agentsConsented = gate.write('agents');
  const docsOnDisk = docsWritten || existsSync(join(docsDir, 'agents-index.txt'));
  if (shouldInjectAgents({ agentsConsented, docsOnDisk })) {
    const agentsIndex = resolveAgentsIndex(docsDir, bundledDocs, docsRel);
    processAgentFiles(gate, agentsIndex, projectRoot);
  } else if (agentsConsented) {
    console.log('   Skipping agent-file injection: docs not present at ' + docsRel + '.');
  }

  updateGitignore(gate, projectRoot, docsRel);
  setupCliHooks(gate, rundotDir, version);

  if (docsRequestedButUnavailable) {
    // Don't print the success line on a path that exits non-zero.
    console.error('RUN.world SDK setup failed: docs were requested but unavailable.');
    process.exit(1);
  }

  console.log('RUN.world SDK setup complete.');
}

// Only run when invoked directly (not when imported by tests). npm installs the
// bin as a symlink, so resolve both sides through realpath before comparing.
const invokedPath = process.argv[1] ? realpathSync(process.argv[1]) : '';
if (invokedPath === realpathSync(__filename)) {
  main().catch((err) => {
    console.error('rundot-sdk-setup failed:', err.message);
    process.exit(1);
  });
}
